	t.Chdir(repoDir)
	runGitInDir(t, ".", "remote", "add", "origin", "https://github.com/acme/widget.git")

	scope, err := currentTrailEnablementScope(t.Context())
	if err != nil {
		t.Fatalf("resolve trail scope: %v", err)
	}

