     6		"io/fs"
     7		"os"
     8		"path/filepath"
     9		"strings"
    10	)
    11	
    12	// ErrWorktreeMetadataNotFound reports that an explicit worktree root has no
    13	// .git entry. Repository opening uses this to distinguish a possible bare
    14	// repository from malformed metadata in a checkout.
    15	var ErrWorktreeMetadataNotFound = errors.New("worktree Git metadata not found")
    16	
    17	// WorktreeMetadata contains Git directory facts for one explicit worktree
    18	// root. Paths are cleaned and absolute but retain their lexical spelling;
    19	// WorktreeID uses physical directory identity internally.
    20	type WorktreeMetadata struct {
    21		GitDir     string
    22		CommonDir  string
    23		WorktreeID string
    24	}
    25	
    26	// ResolveWorktreeMetadata resolves filesystem metadata for an explicit
    27	// worktree root. It does not discover a root, inspect Git environment
    28	// variables, run Git, cache results, or decide feature-specific policy.
    29	func ResolveWorktreeMetadata(worktreeRoot string) (WorktreeMetadata, error) {
    30		if strings.TrimSpace(worktreeRoot) == "" {
    31			return WorktreeMetadata{}, errors.New("worktree root is required")
    32		}
    33	
    34		root, err := filepath.Abs(worktreeRoot)
    35		if err != nil {
    36			return WorktreeMetadata{}, fmt.Errorf("resolve worktree root %q: %w", worktreeRoot, err)
    37		}
    38		root = filepath.Clean(root)
    39	
    40		gitDir, err := resolveWorktreeGitDir(root)
    41		if err != nil {
    42			return WorktreeMetadata{}, err
    43		}
    44		commonDir, err := resolveWorktreeCommonDir(gitDir)
    45		if err != nil {
    46			return WorktreeMetadata{}, err
    47		}
    48		worktreeID, err := resolveWorktreeID(gitDir, commonDir)
    49		if err != nil {
    50			return WorktreeMetadata{}, err
    51		}
    52	
    53		return WorktreeMetadata{
    54			GitDir:     gitDir,
    55			CommonDir:  commonDir,
    56			WorktreeID: worktreeID,
    57		}, nil
    58	}
    59	
    60	func resolveWorktreeGitDir(worktreeRoot string) (string, error) {
    61		gitEntry := filepath.Join(worktreeRoot, gitDir)
    62		info, err := os.Lstat(gitEntry)
    63		if errors.Is(err, fs.ErrNotExist) {
    64			return "", fmt.Errorf("%w at %s: %w", ErrWorktreeMetadataNotFound, gitEntry, err)
    65		}
    66		if err != nil {
    67			return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
    68		}
    69		if info.Mode()&fs.ModeSymlink != 0 {
    70			info, err = os.Stat(gitEntry)
    71			if err != nil {
    72				return "", fmt.Errorf("inspect .git entry at %s: %w", gitEntry, err)
    73			}
    74		}
    75		if info.IsDir() {
    76			return gitEntry, nil
    77		}
    78		if !info.Mode().IsRegular() {
    79			return "", fmt.Errorf(".git entry at %s is neither a directory nor a regular file", gitEntry)
    80		}
    81	
    82		content, err := os.ReadFile(gitEntry) //nolint:gosec // path is anchored at the explicit worktree root.
    83		if err != nil {
    84			return "", fmt.Errorf("read .git file at %s: %w", gitEntry, err)
    85		}
    86		pointer, ok := strings.CutPrefix(strings.TrimRight(string(content), "\r\n"), "gitdir: ")
    87		if !ok {
    88			return "", fmt.Errorf("parse .git file at %s: missing gitdir prefix", gitEntry)
    89		}
    90		if pointer == "" {
    91			return "", fmt.Errorf("parse .git file at %s: empty gitdir value", gitEntry)
    92		}
    93	
    94		resolved := resolveMetadataPath(worktreeRoot, pointer)
    95		if err := requireDirectory("Git directory", resolved); err != nil {
    96			return "", err
    97		}
    98		return filepath.Clean(resolved), nil
    99	}
   100	
   101	func resolveWorktreeCommonDir(gitDirPath string) (string, error) {
   102		commonFile := filepath.Join(gitDirPath, "commondir")
   103		info, err := os.Lstat(commonFile)
   104		if errors.Is(err, fs.ErrNotExist) {
   105			return gitDirPath, nil
   106		}
   107		if err != nil {
