   104		if errors.Is(err, fs.ErrNotExist) {
   105			return gitDirPath, nil
   106		}
   107		if err != nil {
   108			return "", fmt.Errorf("inspect commondir file at %s: %w", commonFile, err)
   109		}
   110		if !info.Mode().IsRegular() {
   111			return "", fmt.Errorf("commondir entry at %s is not a regular file", commonFile)
   112		}
   113	
   114		content, err := os.ReadFile(commonFile) //nolint:gosec // path is inside the validated per-worktree Git directory.
   115		if err != nil {
   116			return "", fmt.Errorf("read commondir file at %s: %w", commonFile, err)
   117		}
   118		pointer := strings.TrimRight(string(content), "\r\n")
   119		if pointer == "" {
   120			return "", fmt.Errorf("parse commondir file at %s: empty value", commonFile)
   121		}
   122	
   123		resolved := resolveMetadataPath(gitDirPath, pointer)
   124		if err := requireDirectory("common Git directory", resolved); err != nil {
   125			return "", err
   126		}
   127		return filepath.Clean(resolved), nil
   128	}
   129	
   130	func resolveWorktreeID(gitDirPath, commonDir string) (string, error) {
   131		same, err := directoriesIdentifySameFile(gitDirPath, commonDir)
   132		if err != nil {
   133			return "", fmt.Errorf("compare Git and common directories: %w", err)
   134		}
   135		if same {
   136			return "", nil
   137		}
   138	
   139		registrationRoot := filepath.Join(commonDir, "worktrees")
   140		same, err = directoriesIdentifySameFile(filepath.Dir(gitDirPath), registrationRoot)
   141		if err != nil {
   142			return "", fmt.Errorf("validate linked-worktree registration for %s: %w", gitDirPath, err)
   143		}
   144		if !same {
   145			return "", fmt.Errorf("git directory %s is not an immediate child of %s", gitDirPath, registrationRoot)
   146		}
   147	
   148		id := filepath.Base(gitDirPath)
   149		if id == "." || id == string(filepath.Separator) || id == "" {
   150			return "", fmt.Errorf("git directory %s has no worktree registration name", gitDirPath)
   151		}
   152		return id, nil
   153	}
   154	
   155	// Keep every component until after validation so malformed paths cannot use
   156	// lexical cleaning to bypass a missing intermediate directory.
   157	func resolveMetadataPath(base, value string) string {
   158		if filepath.IsAbs(value) {
   159			return value
   160		}
   161		return base + string(filepath.Separator) + value
   162	}
   163	
   164	func requireDirectory(label, path string) error {
   165		info, err := os.Stat(path) //nolint:gosec // the explicit-root API intentionally resolves caller-selected repository metadata.
   166		if err != nil {
   167			return fmt.Errorf("inspect %s at %s: %w", label, path, err)
   168		}
   169		if !info.IsDir() {
   170			return fmt.Errorf("%s at %s is not a directory", label, path)
   171		}
   172		return nil
   173	}
   174	
   175	func directoriesIdentifySameFile(a, b string) (bool, error) {
   176		aInfo, err := os.Stat(a)
   177		if err != nil {
   178			return false, fmt.Errorf("inspect %s: %w", a, err)
   179		}
   180		if !aInfo.IsDir() {
   181			return false, fmt.Errorf("%s is not a directory", a)
   182		}
   183		bInfo, err := os.Stat(b)
   184		if err != nil {
   185			return false, fmt.Errorf("inspect %s: %w", b, err)
   186		}
   187		if !bInfo.IsDir() {
   188			return false, fmt.Errorf("%s is not a directory", b)
   189		}
   190		return os.SameFile(aInfo, bInfo), nil
   191	}
